<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$d=request_json();verify_csrf($d['_csrf']??'');$f=owned_file((int)($d['id']??0),$u['id']);$expires=$d['expires']??'1d';$map=['1h'=>3600,'1d'=>86400,'7d'=>604800,'30d'=>2592000];$seconds=$map[$expires]??86400;$exp=date('Y-m-d H:i:s',time()+$seconds);$token=safe_share_token();db()->prepare('INSERT INTO shares(user_id,file_id,token,permission,expires_at) VALUES(?,?,?,?,?)')->execute([$u['id'],$f['id'],$token,$d['permission']??'view_download',$exp]);$url=rtrim(envv('APP_URL','http://localhost/FluxDrive/public'),'/').'/share.php?token='.rawurlencode($token);log_activity($u['id'],'Share',$f['id'],$f['folder_id'],'Shared '.$f['file_name']);json_response(['ok'=>1,'url'=>$url,'expires_at'=>$exp]);